#' Empirical level or power of a goodness-of-fit test
#'
#' Repeats \code{\link{test_gof}} on \code{h} independent data sets
#' generated by \code{gen_X}, and returns the average rejection rate for
#' each of the 4 statistics. This is the empirical level if \code{gen_X}
#' simulates under \eqn{H_0}, the power otherwise. A replication for
#' which \code{test_gof} fails (for example, negative increments
#' incompatible with a Gamma or IG model) is counted as a rejection on
#' all 4 statistics: data that cannot even be fitted by the candidate
#' model is, by nature, not consistent with it.
#'
#' @param h Integer number of replications.
#' @param gen_X Function \code{function() -> matrix}, generating the data
#'   set at each replication.
#' @param T Vector of the observation times.
#' @param est Estimation function, see \code{\link{test_gof}}.
#' @param sim Simulation function, see \code{\link{test_gof}}.
#' @param mp Size of the simulated pool (\eqn{m'}).
#' @param L Number of bootstrap replications.
#' @param alpha Significance level of the test. Defaults to 0.05.
#'
#' @return Named numeric vector of length 4, rejection rate rounded to 4
#'   decimal places for each statistic.
#'
#' @examples
#' T <- 1:50
#' gen_h0 <- function() sim_proc(T, list(mu_W = 0.2, sigma = 0.05), "Wiener", mp = 6)
#' etude_puissance(h = 10, gen_h0, T, est_modele("Wiener"), sim_modele("Wiener"),
#'                 mp = 300, L = 50)
#'
#' @export
etude_puissance <- function(h, gen_X, T, est, sim, mp, L, alpha = 0.05) {
    rejets <- vector("list", h)
    for (r in seq_len(h)) {
          rejets[[r]] <- tryCatch(
                  test_gof(gen_X(), T, est, sim, mp = mp, L = L, alpha = alpha)$rejet,
                  error = function(e) c(KS_sup = TRUE, KS_sum = TRUE, CvM_sup = TRUE, CvM_sum = TRUE)
                )
        }
    round(colMeans(do.call(rbind, rejets)), 4)
  }
